const $=s=>document.querySelector(s);const bank='the be of and a to in he have it that for they with as not on she at by this we you do but from or which one would all will there say who make when can more if no man out other so what time up go about than into could state only new year some take come these know see use get like then first any work now may such give over think most even find day also after way many must look before great back through long where much should well people down own just because good each those feel seem how high too place little world very still nation hand old life tell write become here show house both between need mean call develop under last right move thing general school never same another begin while number part turn real leave might want point form off child few small since against ask late home interest large person end open public follow during present without again hold around possible head consider word program problem however lead system set order eye plan run keep face fact group play stand increase early course change help line'.split(' ');let mode='time',limit=30,punctuation=false,numbers=false,words='',typed='',start=0,timer=null,done=false,attempts=0,errors=0;let history=[];try{history=JSON.parse(localStorage.getItem('flowtype-history')||'[]')}catch{}function lengths(){ $('#lengths').innerHTML=(mode==='time'?[15,30,60,120]:[10,25,50,100]).map(n=>`<button data-limit="${n}" class="${n===limit?'selected':''}">${n}</button>`).join('')}function generate(){return Array.from({length:mode==='words'?limit:250},()=>{let w=bank[Math.floor(Math.random()*bank.length)];if(numbers&&Math.random()<.12)w=String(Math.floor(Math.random()*1000));if(punctuation&&Math.random()<.18)w+=['.',',',';','?'][Math.floor(Math.random()*4)];return w}).join(' ')}function render(){const frag=document.createDocumentFragment();for(let i=0;i<words.length;i++){let s=document.createElement('span');s.textContent=words[i];s.className=(i<typed.length?(typed[i]===words[i]?'correct':'wrong'):'')+(i===typed.length?' current':'');frag.append(s)}$('#words').replaceChildren(frag);const current=$('#words .current');if(current)$('#arena').scrollTop=Math.max(0,current.offsetTop-$('#words').offsetTop-50)}function reset(){clearInterval(timer);timer=null;typed='';start=0;done=false;attempts=0;errors=0;words=generate();$('#results').hidden=true;$('#status').textContent='ready when you are';$('#hint').textContent='The timer starts with your first keystroke';$('#arena').scrollTop=0;render()}function stats(){let seconds=Math.max(.1,(Date.now()-start)/1000),correct=[...typed].filter((c,i)=>c===words[i]).length;return{wpm:Math.round(correct/5/(seconds/60)),accuracy:attempts?Math.round((attempts-errors)/attempts*100):100,seconds:Math.round(seconds),correct}}function finish(){if(done)return;done=true;clearInterval(timer);let s=stats();$('#results').hidden=false;$('#wpm').textContent=s.wpm;$('#accuracy').textContent=s.accuracy+'%';$('#chars').textContent=s.correct;$('#elapsed').textContent=s.seconds+'s';$('#status').textContent='nicely done ✧';$('#hint').textContent='Take a breath. Try another.';history.unshift({...s,date:Date.now(),mode,limit});history=history.slice(0,50);try{localStorage.setItem('flowtype-history',JSON.stringify(history))}catch{}}function tick(){let s=stats();$('#status').textContent=mode==='time'?Math.max(0,limit-s.seconds)+'s remaining':typed.split(' ').length+' / '+limit+' words';$('#hint').textContent=s.wpm+' wpm · '+s.accuracy+'% accuracy';if(mode==='time'&&Date.now()-start>=limit*1000)finish()}document.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.activeElement===$('#restart')){e.preventDefault();reset();$('#arena').focus();return}if(e.key==='Tab'||e.ctrlKey||e.metaKey||e.altKey||$('#practice').hidden)return;if(e.target.tagName==='BUTTON'&&e.key==='Enter')return;if(e.key==='Backspace'){e.preventDefault();if(!done){typed=typed.slice(0,-1);render()}return}if(e.key.length!==1||done)return;e.preventDefault();$('#arena').focus();if(!start){start=Date.now();timer=setInterval(tick,100)}attempts++;if(e.key!==words[typed.length])errors++;typed+=e.key;render();tick();if(typed.length>=words.length)finish()});$('#restart').onclick=()=>{reset();$('#arena').focus()};$('#modes').onclick=e=>{if(!e.target.dataset.mode)return;mode=e.target.dataset.mode;limit=mode==='time'?30:25;$('#modes').querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));lengths();reset()};$('#lengths').onclick=e=>{if(!e.target.dataset.limit)return;limit=Number(e.target.dataset.limit);lengths();reset()};for(const id of ['punct','numbers'])$('#'+id).onclick=()=>{if(id==='punct')punctuation=!punctuation;else numbers=!numbers;$('#'+id).classList.toggle('selected',id==='punct'?punctuation:numbers);reset()};$('#theme').onclick=()=>document.body.classList.toggle('light');function page(name){if(name==='history'&&start&&!done)reset();$('#practice').hidden=name!=='practice';$('#history').hidden=name!=='history';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#history-list').replaceChildren();if(!history.length)$('#history-list').innerHTML='<p>Your first session is a fresh start. Complete a test to see it here.</p>';for(const s of history){let row=document.createElement('div');row.className='history-row';for(const text of [new Date(s.date).toLocaleDateString(),s.wpm+' wpm',s.accuracy+'% accuracy',s.mode==='time'?s.limit+' seconds':s.limit+' words']){let cell=document.createElement('span');cell.textContent=text;row.append(cell)}$('#history-list').append(row)}}document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>page(b.dataset.page));$('#back').onclick=()=>page('practice');lengths();reset();
